package passthrough

import (
	"encoding/json"
	"os"
	"reflect"
	"strings"
	"testing"
)

// node_vectors.json is generated by testdata/gen-vectors.js from the Node
// core's compiled remux-args / mpegts-source / mediamtx-path utils.
type nodeVectors struct {
	HlsDir string `json:"hlsDir"`
	Remux  []struct {
		In struct {
			App, StreamKey, HlsDir, Transport, Mode, SourceURL, BindHost, PullHost string
			Port, HlsTime, HlsListSize                                             int
		} `json:"in"`
		Args []string `json:"args"`
	} `json:"remux"`
	Forward []struct {
		In struct {
			Key                  string
			SourcePort, DestPort int
			Host                 string
		} `json:"in"`
		Args []string `json:"args"`
	} `json:"forward"`
	Mpegts []struct {
		In              map[string]any `json:"in"`
		SourceURL       string         `json:"sourceUrl"`
		Host            string         `json:"host"`
		Port            int            `json:"port"`
		Multicast       bool           `json:"multicast"`
		SsmSources      []string       `json:"ssmSources"`
		BlockSources    []string       `json:"blockSources"`
		Localaddr       *string        `json:"localaddr"`
		FifoSize        *int           `json:"fifoSize"`
		OverrunNonfatal bool           `json:"overrunNonfatal"`
		Error           string         `json:"error"`
	} `json:"mpegts"`
	Paths []struct {
		In  string `json:"in"`
		Out struct {
			Kind, App, Key string
		} `json:"out"`
	} `json:"paths"`
}

func loadVectors(t *testing.T) nodeVectors {
	t.Helper()
	b, err := os.ReadFile("testdata/node_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v nodeVectors
	// The remux "in" objects use Node's camelCase keys.
	s := strings.NewReplacer(`"streamKey"`, `"StreamKey"`, `"hlsDir"`, `"HlsDir"`, `"sourceUrl":`, `"SourceUrl":`,
		`"bindHost"`, `"BindHost"`, `"pullHost"`, `"PullHost"`, `"hlsListSize"`, `"HlsListSize"`,
		`"sourcePort"`, `"SourcePort"`, `"destPort"`, `"DestPort"`).Replace(string(b))
	if err := json.Unmarshal([]byte(s), &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func TestRemuxArgsVectors(t *testing.T) {
	v := loadVectors(t)
	if got := HlsDir("/data", "live", "live-ch1"); got != v.HlsDir {
		t.Fatalf("HlsDir = %q, want %q", got, v.HlsDir)
	}
	for i, c := range v.Remux {
		got := BuildRemuxArgs(RemuxArgs{
			App: c.In.App, StreamKey: c.In.StreamKey, Port: c.In.Port, HlsDir: c.In.HlsDir, Transport: c.In.Transport,
			Mode: c.In.Mode, SourceURL: c.In.SourceURL, BindHost: c.In.BindHost, PullHost: c.In.PullHost,
			HlsTime: c.In.HlsTime, ListSize: c.In.HlsListSize,
		})
		if !reflect.DeepEqual(got, c.Args) {
			t.Errorf("remux #%d:\n got %q\nwant %q", i, got, c.Args)
		}
	}
	for i, c := range v.Forward {
		if got := BuildForwardArgs(c.In.Key, c.In.SourcePort, c.In.DestPort, c.In.Host); !reflect.DeepEqual(got, c.Args) {
			t.Errorf("forward #%d:\n got %q\nwant %q", i, got, c.Args)
		}
	}
	if len(v.Remux) < 9 || len(v.Forward) < 2 {
		t.Fatal("vectors truncated")
	}
}

// The REMUX invariant: every argv stream-copies, never re-encodes.
func TestRemuxNeverTranscodes(t *testing.T) {
	for _, tr := range []string{"", TransportSRT, TransportMPEGTS} {
		args := strings.Join(BuildRemuxArgs(RemuxArgs{App: "a", StreamKey: "k", Port: 1, HlsDir: "/x", Transport: tr}), " ")
		if !strings.Contains(args, "-c copy") || strings.Contains(args, "libx264") || strings.Contains(args, "-c:v") {
			t.Errorf("%q: %s", tr, args)
		}
		if tr != "" && strings.Contains(args, "-listen") {
			t.Errorf("%q must not use -listen: %s", tr, args)
		}
	}
}

func TestMpegtsVectors(t *testing.T) {
	v := loadVectors(t)
	for i, c := range v.Mpegts {
		o := MpegtsOptions{URL: c.In["url"].(string)}
		if s, ok := c.In["sources"].(string); ok {
			o.SourcesRaw = &s
		}
		if s, ok := c.In["block"].(string); ok {
			o.BlockRaw = &s
		}
		if s, ok := c.In["localaddr"].(string); ok {
			o.Localaddr = &s
		}
		if f, ok := c.In["fifoSize"].(float64); ok {
			o.FifoSize = &f
		}
		if b, ok := c.In["overrunNonfatal"].(bool); ok {
			o.OverrunNonfatal = &b
		}
		p, err := ParseMpegtsSource(o)
		if c.Error != "" {
			if err == nil || err.Error() != c.Error {
				t.Errorf("#%d %v: err = %v, want %q", i, c.In, err, c.Error)
			}
			continue
		}
		if err != nil {
			t.Errorf("#%d %v: unexpected %v", i, c.In, err)
			continue
		}
		var la *string
		if p.Localaddr != "" {
			la = &p.Localaddr
		}
		if p.SourceURL != c.SourceURL || p.Host != c.Host || p.Port != c.Port || p.Multicast != c.Multicast ||
			!reflect.DeepEqual(p.SsmSources, c.SsmSources) || !reflect.DeepEqual(p.BlockSources, c.BlockSources) ||
			!reflect.DeepEqual(la, c.Localaddr) || !reflect.DeepEqual(p.FifoSize, c.FifoSize) || p.OverrunNonfatal != c.OverrunNonfatal {
			t.Errorf("#%d %v:\n got %+v", i, c.In, p)
		}
	}
}

func TestMpegtsArraySources(t *testing.T) {
	p, err := ParseMpegtsSource(MpegtsOptions{URL: "udp://@232.0.0.1:5000", Sources: []string{" 10.0.0.1 ", "", "10.0.0.2"}})
	if err != nil || p.SourceURL != "udp://@232.0.0.1:5000?sources=10.0.0.1,10.0.0.2&overrun_nonfatal=1" {
		t.Fatalf("%+v %v", p, err)
	}
	if !IsMulticastIPv4("224.0.0.1") || !IsMulticastIPv4("239.255.255.255") || IsMulticastIPv4("240.0.0.1") || IsMulticastIPv4("223.1.1.1") {
		t.Fatal("multicast range")
	}
}

func TestClassifyMediamtxPathVectors(t *testing.T) {
	v := loadVectors(t)
	for _, c := range v.Paths {
		got := ClassifyMediamtxPath(c.In)
		want := PathClass{Kind: c.Out.Kind, App: c.Out.App, Key: c.Out.Key}
		if got != want {
			t.Errorf("%q = %+v, want %+v", c.In, got, want)
		}
	}
}
